-- RETAILOS migration for a DEDICATED Supabase project: port of supabase/migrations/20261010100009_checkout.sql.
-- GENERATED by scripts/port-to-retailos.mjs; sealed in SHA256SUMS and pinned in ../MANIFEST.sha256.
-- Creates and uses only schemas retailos and retailos_private. It reads auth.users (foreign key, ensure_profile) and nothing else outside them.
-- Run only as described in docs/RETAILOS_MIGRATION_RUNBOOK.md, and only after approval.

-- M0009 billing functions: barcode resolution, search, authoritative quote, start of day, and the
-- transactional checkout.
--
-- All money inside these functions is whole PAISE in bigint arithmetic. Table columns are
-- numeric(14,2) rupees; the conversion (x * 100)::bigint and (p / 100.0) is exact.
--
-- Nothing here contains a GST rate, a jewellery pricing rule or a metal rate. Tax comes from
-- tax_rates configured by the owner. A line that needs a rule or rate that has not been configured
-- is refused with a specific code (TAX_NOT_CONFIGURED, RULE_NOT_CONFIGURED).

-- ---------------------------------------------------------------------------------------------
-- Authoritative cart pricing. Used by the preview (pos_quote_cart) and, under locks, by checkout.
--   p_lines: [{"itemId": uuid, "quantity": int, "discountPaise"?: int, "discountReason"?: text}]
-- Returns the priced cart plus `issues` (problems that would block checkout); never raises for
-- business problems, only for malformed input.
-- ---------------------------------------------------------------------------------------------
create or replace function retailos_private.build_quote(p_branch uuid, p_lines jsonb, p_lock boolean)
returns jsonb
language plpgsql
security definer set search_path = ''
as $$
declare
  c_uuid constant text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_tenant uuid;
  v_tz text;
  v_date date;
  v_settings retailos.tenant_settings;
  v_limit integer;
  v_e jsonb;
  v_k text;
  v_ids uuid[];
  r record;
  v_var record;
  v_item record;
  v_on_hand integer;
  v_issue text;
  v_lines jsonb := '[]'::jsonb;
  v_issues jsonb := '[]'::jsonb;
  v_unit bigint; v_gross bigint; v_disc bigint; v_net bigint;
  v_taxable bigint; v_tax bigint; v_cgst bigint; v_sgst bigint; v_line_total bigint;
  v_rate numeric; v_include boolean; v_class uuid; v_hsn text;
  v_kind text; v_name text; v_detail text; v_code text; v_type text; v_mode text; v_unique boolean; v_max integer;
  v_sum_total bigint := 0; v_sum_disc bigint := 0; v_sum_tax bigint := 0; v_sum_taxable bigint := 0;
  v_sum_cgst bigint := 0; v_sum_sgst bigint := 0; v_sum_gross bigint := 0; v_count integer := 0;
begin
  select b.tenant_id, b.timezone into v_tenant, v_tz from retailos.branches b where b.id = p_branch;
  v_date := (now() at time zone v_tz)::date;
  select * into v_settings from retailos.tenant_settings where tenant_id = v_tenant;
  v_limit := retailos_private.discount_limit_bps(p_branch);

  -- ---- validate the request shape (malformed input is an error, not an empty cart) ----
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) > 200 then
    perform retailos_private.fail('VALIDATION_ERROR');
  end if;
  for v_e in select * from jsonb_array_elements(p_lines) loop
    if jsonb_typeof(v_e) <> 'object' then perform retailos_private.fail('VALIDATION_ERROR'); end if;
    for v_k in select jsonb_object_keys(v_e) loop
      if v_k not in ('itemId', 'quantity', 'discountPaise', 'discountReason') then
        perform retailos_private.fail('VALIDATION_ERROR', jsonb_build_object('field', v_k));
      end if;
    end loop;
    if jsonb_typeof(v_e -> 'itemId') <> 'string' or (v_e ->> 'itemId') !~ c_uuid
       or jsonb_typeof(v_e -> 'quantity') <> 'number' or (v_e ->> 'quantity') !~ '^[1-9][0-9]{0,2}$'
       or (v_e ? 'discountPaise' and ((jsonb_typeof(v_e -> 'discountPaise') <> 'number') or (v_e ->> 'discountPaise') !~ '^[0-9]{1,12}$'))
       or (v_e ? 'discountReason' and jsonb_typeof(v_e -> 'discountReason') <> 'string') then
      perform retailos_private.fail('VALIDATION_ERROR');
    end if;
  end loop;
  select array_agg((e ->> 'itemId')::uuid) into v_ids from jsonb_array_elements(p_lines) e;
  if v_ids is not null and (select count(distinct x) from unnest(v_ids) x) <> array_length(v_ids, 1) then
    perform retailos_private.fail('VALIDATION_ERROR', jsonb_build_object('field', 'duplicate item'));
  end if;

  -- ---- locks, in one fixed order everywhere: variants (share), jewellery items, balances ----
  if p_lock and v_ids is not null then
    perform 1 from retailos.product_variants where tenant_id = v_tenant and id = any (v_ids) order by id for share;
    perform 1 from retailos.jewellery_items where tenant_id = v_tenant and id = any (v_ids) order by id for update;
    perform 1 from retailos.inventory_balances where branch_id = p_branch and variant_id = any (v_ids) order by variant_id for update;
  end if;

  -- ---- price each line ----
  for r in
    select (e ->> 'itemId')::uuid as item_id,
           (e ->> 'quantity')::integer as qty,
           coalesce((e ->> 'discountPaise')::bigint, 0) as disc,
           btrim(coalesce(e ->> 'discountReason', '')) as reason
    from jsonb_array_elements(p_lines) e
    order by 1
  loop
    v_issue := null;
    v_class := null;

    select pv.id, pv.sku, pv.size_label, pv.colour_label, pv.selling_price, pv.is_active as v_active,
           p.name as pname, p.is_active as p_active, p.hsn_code as p_hsn, p.tax_class_id as p_tax, pv.tax_class_id as v_tax,
           c.hsn_code as c_hsn, c.tax_class_id as c_tax
      into v_var
      from retailos.product_variants pv
      join retailos.products p on p.tenant_id = pv.tenant_id and p.id = pv.product_id
      join retailos.categories c on c.tenant_id = p.tenant_id and c.id = p.category_id
     where pv.tenant_id = v_tenant and pv.id = r.item_id;

    if found then
      v_type := 'VARIANT'; v_kind := 'CLOTHING'; v_mode := 'VARIANT_PRICE'; v_unique := false;
      v_name := v_var.pname; v_detail := v_var.size_label || ' / ' || v_var.colour_label; v_code := v_var.sku;
      v_unit := (v_var.selling_price * 100)::bigint;
      v_class := coalesce(v_var.v_tax, v_var.p_tax, v_var.c_tax);
      v_hsn := coalesce(v_var.p_hsn, v_var.c_hsn);
      select coalesce(on_hand, 0) into v_on_hand from retailos.inventory_balances
        where branch_id = p_branch and variant_id = r.item_id;
      v_on_hand := coalesce(v_on_hand, 0);
      v_max := v_on_hand;
      if not (v_var.v_active and v_var.p_active) then v_issue := 'ITEM_INACTIVE';
      elsif r.qty > v_on_hand then v_issue := 'INSUFFICIENT_STOCK'; end if;
    else
      select ji.id, ji.tag_code, ji.status, ji.pricing_mode, ji.tag_price, ji.branch_id, ji.is_active as i_active, ji.kind,
             jd.name as dname, jd.is_active as d_active, jd.hsn_code as d_hsn, jd.tax_class_id as d_tax,
             c.hsn_code as c_hsn, c.tax_class_id as c_tax
        into v_item
        from retailos.jewellery_items ji
        join retailos.jewellery_designs jd on jd.tenant_id = ji.tenant_id and jd.id = ji.design_id
        join retailos.categories c on c.tenant_id = jd.tenant_id and c.id = jd.category_id
       where ji.tenant_id = v_tenant and ji.id = r.item_id;
      if found then
        v_type := 'JEWELLERY_ITEM'; v_unique := true; v_max := 1;
        v_kind := case v_item.kind when 'IMITATION' then 'IMITATION_JEWELLERY' else 'PRECIOUS_JEWELLERY' end;
        v_mode := v_item.pricing_mode; v_name := v_item.dname; v_detail := v_item.tag_code; v_code := v_item.tag_code;
        v_unit := coalesce((v_item.tag_price * 100)::bigint, 0);
        v_class := coalesce(v_item.d_tax, v_item.c_tax);
        v_hsn := coalesce(v_item.d_hsn, v_item.c_hsn);
        if v_item.branch_id <> p_branch then v_issue := 'ITEM_NOT_IN_BRANCH';
        elsif not (v_item.i_active and v_item.d_active) then v_issue := 'ITEM_INACTIVE';
        elsif v_item.status = 'SOLD' then v_issue := 'ITEM_ALREADY_SOLD';
        elsif v_item.status = 'QC_HOLD' then v_issue := 'ITEM_ON_HOLD';
        elsif v_item.status <> 'IN_STOCK' then v_issue := 'ITEM_INACTIVE';
        elsif r.qty <> 1 then v_issue := 'VALIDATION_ERROR';
        elsif v_item.pricing_mode = 'METAL_RATE' then v_issue := 'RULE_NOT_CONFIGURED'; end if;
      else
        v_issues := v_issues || jsonb_build_object('itemId', r.item_id, 'code', 'ITEM_NOT_FOUND');
        continue;
      end if;
    end if;

    v_gross := v_unit * r.qty;
    v_disc := least(r.disc, v_gross);
    if v_issue is null and r.disc > 0 then
      if r.disc > v_gross or r.disc * 10000 > v_gross * v_limit then v_issue := 'DISCOUNT_NOT_ALLOWED';
      elsif r.reason = '' then v_issue := 'DISCOUNT_REASON_REQUIRED'; end if;
    end if;
    v_net := v_gross - v_disc;

    -- ---- tax (only from configured data; never a built-in rate) ----
    v_taxable := v_net; v_tax := 0; v_cgst := 0; v_sgst := 0; v_rate := null; v_include := null;
    if v_settings.tax_enforced then
      v_include := case when v_kind = 'CLOTHING' then v_settings.prices_include_tax_clothing
                        else v_settings.prices_include_tax_jewellery end;
      if v_class is not null then
        select tr.gst_rate_pct into v_rate from retailos.tax_rates tr
         where tr.tenant_id = v_tenant and tr.tax_class_id = v_class
           and tr.effective_from <= v_date and (tr.effective_to is null or tr.effective_to > v_date);
      end if;
      if v_include is null or v_rate is null then
        v_issue := coalesce(v_issue, 'TAX_NOT_CONFIGURED');
        v_rate := coalesce(v_rate, 0);
      end if;
      if v_include then
        v_taxable := floor(v_net * 100 / (100 + v_rate) + 0.5)::bigint;
        v_tax := v_net - v_taxable;
        v_line_total := v_net;
      else
        v_tax := floor(v_net * v_rate / 100 + 0.5)::bigint;
        v_line_total := v_net + v_tax;
      end if;
      v_cgst := v_tax / 2;            -- integer division; the odd paisa goes to SGST
      v_sgst := v_tax - v_cgst;
    else
      v_line_total := v_net;           -- tax not enforced: nothing computed, flagged on the invoice
    end if;

    if v_issue is not null then
      v_issues := v_issues || jsonb_build_object('itemId', r.item_id, 'code', v_issue);
    end if;

    v_count := v_count + r.qty;
    v_sum_total := v_sum_total + v_line_total; v_sum_disc := v_sum_disc + v_disc; v_sum_gross := v_sum_gross + v_gross;
    v_sum_tax := v_sum_tax + v_tax; v_sum_taxable := v_sum_taxable + v_taxable;
    v_sum_cgst := v_sum_cgst + v_cgst; v_sum_sgst := v_sum_sgst + v_sgst;

    v_lines := v_lines || jsonb_build_object(
      'itemId', r.item_id, 'itemType', v_type, 'kind', v_kind, 'name', v_name, 'detail', v_detail, 'code', v_code,
      'quantity', r.qty, 'unitPricePaise', v_unit, 'grossPaise', v_gross, 'discountPaise', v_disc,
      'discountReason', case when v_disc > 0 then r.reason end,
      'taxableValuePaise', v_taxable, 'taxPaise', v_tax, 'cgstPaise', v_cgst, 'sgstPaise', v_sgst,
      'gstRatePct', v_rate, 'pricesIncludeTax', v_include, 'taxClassId', v_class, 'hsnCode', v_hsn,
      'pricingMode', v_mode, 'lineTotalPaise', v_line_total, 'unique', v_unique, 'maxQuantity', v_max);
  end loop;

  return jsonb_build_object(
    'lines', v_lines, 'itemCount', v_count,
    'grossTotalPaise', v_sum_gross, 'discountTotalPaise', v_sum_disc,
    'taxableTotalPaise', v_sum_taxable, 'taxTotalPaise', v_sum_tax,
    'cgstTotalPaise', v_sum_cgst, 'sgstTotalPaise', v_sum_sgst,
    'grandTotalPaise', v_sum_total, 'taxConfigured', v_settings.tax_enforced, 'issues', v_issues);
end;
$$;

-- ---------------------------------------------------------------------------------------------
-- Read functions for the counter
-- ---------------------------------------------------------------------------------------------
create or replace function retailos.pos_quote_cart(p_branch uuid, p_lines jsonb)
returns jsonb
language plpgsql
security definer set search_path = ''
as $$
begin
  perform retailos_private.assert_branch_permission(p_branch, 'sale.create');
  return retailos_private.build_quote(p_branch, p_lines, false);
end;
$$;

-- EXACT barcode lookup. Compares the normalised value for equality; there is no LIKE, prefix or
-- fuzzy path, so a partial code can never resolve to an item.
create or replace function retailos.resolve_barcode(p_branch uuid, p_code text)
returns jsonb
language plpgsql
security definer set search_path = ''
as $$
declare
  v_tenant uuid;
  v_norm text;
  v_row retailos.barcode_aliases;
begin
  perform retailos_private.assert_branch_permission(p_branch, 'sale.create');
  select tenant_id into v_tenant from retailos.branches where id = p_branch;
  v_norm := upper(btrim(regexp_replace(coalesce(p_code, ''), '[\x00-\x1f\x7f]', '', 'g')));
  if v_norm !~ '^[A-Z0-9]{4,48}$' then perform retailos_private.fail('BARCODE_NOT_FOUND'); end if;
  select * into v_row from retailos.barcode_aliases where tenant_id = v_tenant and code = v_norm and is_active;
  if not found then perform retailos_private.fail('BARCODE_NOT_FOUND'); end if;
  return jsonb_build_object('itemId', coalesce(v_row.variant_id, v_row.jewellery_item_id), 'itemType', v_row.target_type);
end;
$$;

-- Name search. Looks only at names, size/colour, brand and style/design codes. Barcodes and tag
-- codes are never searched, so a partial barcode cannot match an item.
create or replace function retailos.catalog_search(p_branch uuid, p_query text)
returns jsonb
language plpgsql
security definer set search_path = ''
as $$
declare
  v_tenant uuid;
  v_tokens text[];
  v_out jsonb;
begin
  perform retailos_private.assert_branch_permission(p_branch, 'sale.create');
  select tenant_id into v_tenant from retailos.branches where id = p_branch;
  if p_query is null or length(p_query) > 80 then perform retailos_private.fail('VALIDATION_ERROR'); end if;
  v_tokens := array(select t from unnest(regexp_split_to_array(lower(btrim(p_query)), '\s+')) t where t <> '');
  if coalesce(array_length(v_tokens, 1), 0) = 0 or length(array_to_string(v_tokens, '')) < 2 then
    return '[]'::jsonb;
  end if;

  select coalesce(jsonb_agg(x order by x ->> 'name', x ->> 'detail'), '[]'::jsonb) into v_out from (
    select jsonb_build_object(
             'itemId', pv.id, 'kind', 'CLOTHING', 'name', p.name,
             'detail', pv.size_label || ' / ' || pv.colour_label,
             'unitPricePaise', (pv.selling_price * 100)::bigint,
             'available', (pv.is_active and p.is_active
                           and coalesce((select on_hand from retailos.inventory_balances ib
                                          where ib.branch_id = p_branch and ib.variant_id = pv.id), 0) > 0)) as x
      from retailos.product_variants pv
      join retailos.products p on p.tenant_id = pv.tenant_id and p.id = pv.product_id
      left join retailos.brands b on b.tenant_id = p.tenant_id and b.id = p.brand_id
     where pv.tenant_id = v_tenant and pv.is_active and p.is_active
       and not exists (select 1 from unnest(v_tokens) t
                        where position(t in lower(p.name || ' ' || p.style_code || ' ' || pv.size_label || ' ' || pv.colour_label || ' ' || coalesce(b.name, ''))) = 0)
    union all
    select jsonb_build_object(
             'itemId', ji.id,
             'kind', case ji.kind when 'IMITATION' then 'IMITATION_JEWELLERY' else 'PRECIOUS_JEWELLERY' end,
             'name', jd.name, 'detail', ji.tag_code,
             'unitPricePaise', coalesce((ji.tag_price * 100)::bigint, 0),
             'available', (ji.status = 'IN_STOCK' and ji.is_active and jd.is_active and ji.pricing_mode = 'FIXED_TAG'))
      from retailos.jewellery_items ji
      join retailos.jewellery_designs jd on jd.tenant_id = ji.tenant_id and jd.id = ji.design_id
     where ji.tenant_id = v_tenant and ji.branch_id = p_branch and ji.is_active and jd.is_active and ji.status <> 'WRITTEN_OFF'
       and not exists (select 1 from unnest(v_tokens) t
                        where position(t in lower(jd.name || ' ' || jd.design_code)) = 0)
    limit 20
  ) s;
  return v_out;
end;
$$;

-- ---------------------------------------------------------------------------------------------
-- Start of day / session lookup
-- ---------------------------------------------------------------------------------------------
create or replace function retailos.pos_get_session(p_branch uuid, p_counter uuid)
returns jsonb
language plpgsql
security definer set search_path = ''
as $$
declare
  v_s retailos.cash_sessions;
begin
  perform retailos_private.assert_branch_permission(p_branch, 'sale.create');
  select * into v_s from retailos.cash_sessions
   where branch_id = p_branch and counter_id = p_counter and status = 'OPEN';
  if not found then
    return jsonb_build_object('open', false, 'openingFloatPaise', 0, 'openedAt', null, 'sessionId', null);
  end if;
  return jsonb_build_object('open', true, 'openingFloatPaise', (v_s.opening_float * 100)::bigint,
                            'openedAt', v_s.opened_at, 'sessionId', v_s.id);
end;
$$;

create or replace function retailos.pos_start_day(p_branch uuid, p_counter uuid, p_opening_float_paise bigint)
returns jsonb
language plpgsql
security definer set search_path = ''
as $$
declare
  v_tenant uuid;
  v_tz text;
  v_inserted integer;
begin
  perform retailos_private.assert_branch_permission(p_branch, 'cash_session.manage');
  if p_opening_float_paise is null or p_opening_float_paise < 0 or p_opening_float_paise > 100000000000 then
    perform retailos_private.fail('VALIDATION_ERROR');
  end if;
  select tenant_id, timezone into v_tenant, v_tz from retailos.branches where id = p_branch;
  if not exists (select 1 from retailos.counters where id = p_counter and branch_id = p_branch and status = 'ACTIVE') then
    perform retailos_private.fail('VALIDATION_ERROR', jsonb_build_object('field', 'counter'));
  end if;
  insert into retailos.cash_sessions (tenant_id, branch_id, counter_id, business_date, opening_float)
    values (v_tenant, p_branch, p_counter, (now() at time zone v_tz)::date, p_opening_float_paise / 100.0)
  on conflict (counter_id) where status = 'OPEN' do nothing;
  get diagnostics v_inserted = row_count;
  if v_inserted = 1 then
    perform retailos_private.write_audit(v_tenant, p_branch, 'cash_session.open', 'counter', p_counter, null,
              jsonb_build_object('openingFloatPaise', p_opening_float_paise), null, null);
  end if;
  return retailos.pos_get_session(p_branch, p_counter);
end;
$$;

-- ---------------------------------------------------------------------------------------------
-- CHECKOUT. One function = one transaction. Any failure rolls back every effect, including the
-- idempotency record and the invoice number, so a retry with the same key is safe and numbers
-- have no gaps.
--   p_payments: [{"method":"CASH|UPI|CARD","amountPaise":int,"tenderedPaise"?:int,
--                 "confirmedReceived"?:bool,"reference"?:text}]
--   p_customer: {"name"?:text,"phone"?:text} (optional; walk-in sales need none)
-- ---------------------------------------------------------------------------------------------
create or replace function retailos.pos_checkout(
  p_branch uuid, p_counter uuid, p_idempotency_key uuid,
  p_lines jsonb, p_payments jsonb, p_expected_total_paise bigint, p_customer jsonb default null
) returns jsonb
language plpgsql
security definer set search_path = ''
as $$
declare
  v_tenant uuid; v_tz text; v_prefix text; v_state char(2);
  v_settings retailos.tenant_settings;
  v_date date; v_fy text; v_year integer;
  v_hash text; v_replay jsonb;
  v_session retailos.cash_sessions;
  v_quote jsonb; v_issue jsonb;
  v_pay jsonb; v_k text;
  v_applied bigint := 0; v_change bigint := 0; v_tendered bigint;
  v_n bigint; v_number text;
  v_invoice uuid := gen_random_uuid();
  v_line jsonb; v_line_id uuid; v_no integer := 0;
  v_cust_name text; v_cust_phone text;
  v_response jsonb; v_lines_out jsonb := '[]'::jsonb; v_pay_out jsonb := '[]'::jsonb;
  v_total bigint; v_taxable bigint; v_tax bigint;
begin
  -- 1. who is calling, and may they sell in this branch?
  perform retailos_private.assert_branch_permission(p_branch, 'sale.create');
  -- taking the money is a separate permission from creating the sale
  perform retailos_private.assert_branch_permission(p_branch, 'payment.record');
  perform set_config('lock_timeout', '5s', true);
  select b.tenant_id, b.timezone, b.invoice_prefix, b.state_code into v_tenant, v_tz, v_prefix, v_state
    from retailos.branches b where b.id = p_branch;

  -- 2. shape of the request (before any state is touched)
  if p_idempotency_key is null or p_lines is null or jsonb_typeof(p_lines) <> 'array'
     or p_payments is null or jsonb_typeof(p_payments) <> 'array' or jsonb_array_length(p_payments) > 6
     or p_expected_total_paise is null or p_expected_total_paise < 0 then
    perform retailos_private.fail('VALIDATION_ERROR');
  end if;
  if jsonb_array_length(p_lines) = 0 then perform retailos_private.fail('CART_EMPTY'); end if;
  if p_customer is not null then
    if jsonb_typeof(p_customer) <> 'object' then perform retailos_private.fail('VALIDATION_ERROR'); end if;
    for v_k in select jsonb_object_keys(p_customer) loop
      if v_k not in ('name', 'phone') then perform retailos_private.fail('VALIDATION_ERROR'); end if;
    end loop;
    v_cust_name := nullif(btrim(p_customer ->> 'name'), '');
    v_cust_phone := nullif(btrim(p_customer ->> 'phone'), '');
    if length(coalesce(v_cust_name, '')) > 120 or (v_cust_phone is not null and v_cust_phone !~ '^[0-9+ -]{6,20}$') then
      perform retailos_private.fail('VALIDATION_ERROR');
    end if;
  end if;

  -- 3. idempotency: a repeat of the same request returns the original invoice and changes nothing
  v_hash := encode(sha256(convert_to(jsonb_build_object(
      'b', p_branch, 'c', p_counter,
      'l', (select jsonb_agg(e order by e ->> 'itemId') from jsonb_array_elements(p_lines) e),
      'p', p_payments, 't', p_expected_total_paise, 'u', p_customer)::text, 'UTF8')), 'hex');
  v_replay := retailos_private.idem_begin(v_tenant, 'checkout', p_idempotency_key, v_hash);
  if v_replay is not null then
    return v_replay || jsonb_build_object('replayed', true);
  end if;

  -- 4. the day must be started on this counter
  select * into v_session from retailos.cash_sessions
   where branch_id = p_branch and counter_id = p_counter and status = 'OPEN' for share;
  if not found then perform retailos_private.fail('SESSION_NOT_OPEN'); end if;

  -- 5. authoritative pricing under locks (serialized items, then stock rows)
  v_quote := retailos_private.build_quote(p_branch, p_lines, true);
  select * into v_issue from jsonb_array_elements(v_quote -> 'issues') limit 1;
  if v_issue is not null then
    perform retailos_private.fail(v_issue ->> 'code', jsonb_build_object('itemId', v_issue ->> 'itemId', 'quote', v_quote));
  end if;
  if (v_quote ->> 'grandTotalPaise')::bigint <> p_expected_total_paise then
    perform retailos_private.fail('PRICE_STALE', jsonb_build_object('quote', v_quote));
  end if;
  v_total := (v_quote ->> 'grandTotalPaise')::bigint;
  if v_total <= 0 then perform retailos_private.fail('TOTAL_NOT_PAYABLE', jsonb_build_object('quote', v_quote)); end if;

  -- 6. payments must reconcile with the server total, exactly
  if jsonb_array_length(p_payments) = 0 then perform retailos_private.fail('PAYMENT_MISMATCH'); end if;
  for v_pay in select * from jsonb_array_elements(p_payments) loop
    if jsonb_typeof(v_pay) <> 'object' then perform retailos_private.fail('VALIDATION_ERROR'); end if;
    for v_k in select jsonb_object_keys(v_pay) loop
      if v_k not in ('method', 'amountPaise', 'tenderedPaise', 'confirmedReceived', 'reference') then
        perform retailos_private.fail('VALIDATION_ERROR');
      end if;
    end loop;
    if (v_pay ->> 'method') is null or (v_pay ->> 'method') not in ('CASH', 'UPI', 'CARD')
       or jsonb_typeof(v_pay -> 'amountPaise') <> 'number' or (v_pay ->> 'amountPaise') !~ '^[1-9][0-9]{0,11}$'
       or (v_pay ? 'tenderedPaise' and ((jsonb_typeof(v_pay -> 'tenderedPaise') <> 'number') or (v_pay ->> 'tenderedPaise') !~ '^[0-9]{1,12}$'))
       or (v_pay ? 'reference' and (jsonb_typeof(v_pay -> 'reference') <> 'string' or length(v_pay ->> 'reference') > 64)) then
      perform retailos_private.fail('VALIDATION_ERROR');
    end if;
    v_applied := v_applied + (v_pay ->> 'amountPaise')::bigint;
    if v_pay ->> 'method' = 'CASH' then
      v_tendered := coalesce((v_pay ->> 'tenderedPaise')::bigint, (v_pay ->> 'amountPaise')::bigint);
      if v_tendered < (v_pay ->> 'amountPaise')::bigint then perform retailos_private.fail('CASH_TENDER_TOO_LOW'); end if;
      v_change := v_change + (v_tendered - (v_pay ->> 'amountPaise')::bigint);
    elsif coalesce(v_pay -> 'confirmedReceived', 'false'::jsonb) is distinct from 'true'::jsonb then
      -- UPI / card is never assumed received (FR-PAY-04)
      perform retailos_private.fail('PAYMENT_NOT_CONFIRMED');
    end if;
  end loop;
  if v_applied <> v_total then perform retailos_private.fail('PAYMENT_MISMATCH'); end if;

  -- 7. gapless invoice number (the sequence row stays locked until this transaction ends)
  select * into v_settings from retailos.tenant_settings where tenant_id = v_tenant;
  v_date := (now() at time zone v_tz)::date;
  v_year := extract(year from v_date)::integer;
  if extract(month from v_date)::integer >= v_settings.financial_year_start_month then
    v_fy := v_year || '-' || lpad(((v_year + 1) % 100)::text, 2, '0');
  else
    v_fy := (v_year - 1) || '-' || lpad((v_year % 100)::text, 2, '0');
  end if;
  v_n := retailos_private.next_document_number(v_tenant, p_branch, 'INVOICE', v_fy);
  v_number := v_prefix || '-' || lpad(v_n::text, 6, '0');

  -- 8. write the invoice, its snapshots and payments
  v_taxable := (v_quote ->> 'taxableTotalPaise')::bigint;
  v_tax := (v_quote ->> 'taxTotalPaise')::bigint;
  insert into retailos.invoices (id, tenant_id, branch_id, counter_id, cash_session_id, invoice_number, financial_year,
      business_date, cashier_user_id, customer_name, customer_phone, place_of_supply_state_code,
      gross_total, discount_total, taxable_total, cgst_total, sgst_total, igst_total, tax_total, round_off,
      grand_total, paid_total, change_total, tax_configured, idempotency_key)
  values (v_invoice, v_tenant, p_branch, p_counter, v_session.id, v_number, v_fy, v_date, (select auth.uid()),
      v_cust_name, v_cust_phone, v_state,
      (v_quote ->> 'grossTotalPaise')::bigint / 100.0, (v_quote ->> 'discountTotalPaise')::bigint / 100.0,
      v_taxable / 100.0, (v_quote ->> 'cgstTotalPaise')::bigint / 100.0, (v_quote ->> 'sgstTotalPaise')::bigint / 100.0, 0,
      v_tax / 100.0, 0, v_total / 100.0, v_total / 100.0, v_change / 100.0,
      (v_quote ->> 'taxConfigured')::boolean, p_idempotency_key);

  for v_line in select * from jsonb_array_elements(v_quote -> 'lines') loop
    v_no := v_no + 1;
    v_line_id := gen_random_uuid();
    insert into retailos.invoice_items (id, tenant_id, branch_id, invoice_id, line_no, item_type, variant_id, jewellery_item_id,
        product_kind, description, code_snapshot, hsn_code, quantity, unit_price, pricing_mode, price_includes_tax,
        gross_amount, discount_amount, discount_reason, taxable_value, tax_class_id, gst_rate_pct,
        cgst_amount, sgst_amount, igst_amount, line_total)
    values (v_line_id, v_tenant, p_branch, v_invoice, v_no, v_line ->> 'itemType',
        case when v_line ->> 'itemType' = 'VARIANT' then (v_line ->> 'itemId')::uuid end,
        case when v_line ->> 'itemType' = 'JEWELLERY_ITEM' then (v_line ->> 'itemId')::uuid end,
        v_line ->> 'kind', v_line ->> 'name', v_line ->> 'code', v_line ->> 'hsnCode',
        (v_line ->> 'quantity')::integer, (v_line ->> 'unitPricePaise')::bigint / 100.0, v_line ->> 'pricingMode',
        nullif(v_line ->> 'pricesIncludeTax', '')::boolean,
        (v_line ->> 'grossPaise')::bigint / 100.0, (v_line ->> 'discountPaise')::bigint / 100.0,
        nullif(v_line ->> 'discountReason', ''),
        (v_line ->> 'taxableValuePaise')::bigint / 100.0, nullif(v_line ->> 'taxClassId', '')::uuid,
        case when (v_quote ->> 'taxConfigured')::boolean then (v_line ->> 'gstRatePct')::numeric end,
        (v_line ->> 'cgstPaise')::bigint / 100.0, (v_line ->> 'sgstPaise')::bigint / 100.0, 0,
        (v_line ->> 'lineTotalPaise')::bigint / 100.0);

    -- 9. stock and serialized-item effects
    if v_line ->> 'itemType' = 'VARIANT' then
      perform retailos_private.apply_variant_movement(v_tenant, p_branch, (v_line ->> 'itemId')::uuid,
              -((v_line ->> 'quantity')::integer), 'SALE', 'INVOICE', v_invoice, null, null, v_date);
    else
      update retailos.jewellery_items set status = 'SOLD', sold_invoice_item_id = v_line_id
       where tenant_id = v_tenant and id = (v_line ->> 'itemId')::uuid and status = 'IN_STOCK';
      if not found then perform retailos_private.fail('ITEM_ALREADY_SOLD', jsonb_build_object('itemId', v_line ->> 'itemId')); end if;
      perform retailos_private.apply_item_movement(v_tenant, p_branch, (v_line ->> 'itemId')::uuid, -1, 'SALE', 'INVOICE', v_invoice, v_date);
    end if;

    v_lines_out := v_lines_out || jsonb_build_object(
      'name', v_line ->> 'name', 'detail', v_line ->> 'detail', 'quantity', (v_line ->> 'quantity')::integer,
      'unitPricePaise', (v_line ->> 'unitPricePaise')::bigint, 'discountPaise', (v_line ->> 'discountPaise')::bigint,
      'lineTotalPaise', (v_line ->> 'lineTotalPaise')::bigint);
  end loop;

  for v_pay in select * from jsonb_array_elements(p_payments) loop
    v_tendered := coalesce((v_pay ->> 'tenderedPaise')::bigint, (v_pay ->> 'amountPaise')::bigint);
    insert into retailos.payments (tenant_id, branch_id, cash_session_id, invoice_id, method, amount,
        tendered_amount, change_amount, reference_no)
    values (v_tenant, p_branch, v_session.id, v_invoice, v_pay ->> 'method', (v_pay ->> 'amountPaise')::bigint / 100.0,
        case when v_pay ->> 'method' = 'CASH' then v_tendered / 100.0 end,
        case when v_pay ->> 'method' = 'CASH' then (v_tendered - (v_pay ->> 'amountPaise')::bigint) / 100.0 end,
        nullif(v_pay ->> 'reference', ''));
    v_pay_out := v_pay_out || jsonb_build_object('method', v_pay ->> 'method', 'amountPaise', (v_pay ->> 'amountPaise')::bigint);
  end loop;

  -- 10. record the result under the idempotency key, in the same transaction
  v_response := jsonb_build_object(
    'invoiceId', v_invoice, 'invoiceNumber', v_number, 'issuedAt', now(), 'lines', v_lines_out,
    'grandTotalPaise', v_total, 'paidPaise', v_total, 'changePaise', v_change, 'payments', v_pay_out,
    'taxConfigured', (v_quote ->> 'taxConfigured')::boolean, 'taxTotalPaise', v_tax, 'replayed', false);
  perform retailos_private.idem_complete(v_tenant, 'checkout', p_idempotency_key, v_response);
  return v_response;
end;
$$;

-- ---------------------------------------------------------------------------------------------
-- Function privileges: signed-in users only. `anon` and PUBLIC get nothing.
-- ---------------------------------------------------------------------------------------------
revoke execute on all functions in schema retailos_private from public, anon;
revoke execute on function retailos.pos_quote_cart(uuid, jsonb), retailos.resolve_barcode(uuid, text),
  retailos.catalog_search(uuid, text), retailos.pos_get_session(uuid, uuid), retailos.pos_start_day(uuid, uuid, bigint),
  retailos.pos_checkout(uuid, uuid, uuid, jsonb, jsonb, bigint, jsonb) from public, anon;
grant execute on function retailos.pos_quote_cart(uuid, jsonb), retailos.resolve_barcode(uuid, text),
  retailos.catalog_search(uuid, text), retailos.pos_get_session(uuid, uuid), retailos.pos_start_day(uuid, uuid, bigint),
  retailos.pos_checkout(uuid, uuid, uuid, jsonb, jsonb, bigint, jsonb) to authenticated;
